<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api,errorText } from '../api'
import { allowed,date,listItems,roles,statuses } from '../domain'
import type { Row } from '../domain'
import { useAuth } from '../stores/auth'
import { useLoad } from '../composables'
import PageState from '../components/PageState.vue'
import { validateTimeWindow,validateHandoverSelection } from '../workflowForms'

const auth=useAuth(),{loading,error,run}=useLoad(),tab=ref(auth.me?.role==='ADMIN'?'appointments':'delegations'),delegations=ref<Row[]>([]),delegationPolicy=ref<Row>({}),appointments=ref<Row[]>([]),tasks=ref<Row[]>([]),history=ref<Row[]>([]),users=ref<Row[]>([]),targetUsers=ref<Record<string,Row[]>>({}),userId=ref<string|number>(''),selected=ref<Row[]>([]),owners=ref<Record<string,string|number>>({}),transferReason=ref(''),busy=ref(false),operationError=ref(''),drawer=ref(''),form=ref<Row>({}),formError=ref('')
const isAdmin=computed(()=>auth.me?.role==='ADMIN'),canHandover=computed(()=>['DEPT_HEAD','GROUP_LEADER','DIVISION_LEADER','COMPANY_LEADER'].includes(auth.me?.role??'')&&!auth.me?.delegation),canDelegate=computed(()=>auth.me?.role==='DEPT_HEAD'&&!auth.me?.delegation&&allowed(delegationPolicy.value,'create'))
const permissions:Record<string,string>={receive:'接收',assign:'分派',progress:'进度',submit:'提交成果',withdraw:'撤回成果',extend:'申请延期',transfer:'转交',summarize:'汇总',comment:'留言',upload:'上传附件'}
function load(){operationError.value='';run(async()=>{const names=isAdmin.value?['appointments']:['delegations',...(canHandover.value?['handover-tasks','handovers']:[])];const results=await Promise.all(names.map(name=>api.get('/organization/'+name,name==='appointments'&&userId.value?{userId:userId.value}:undefined)));return Object.fromEntries(names.map((name,i)=>[name,results[i]]))},result=>{if(result.appointments)appointments.value=listItems(result.appointments);if(result.delegations){delegationPolicy.value=result.delegations;delegations.value=listItems(result.delegations)};if(result['handover-tasks'])tasks.value=listItems(result['handover-tasks']);if(result.handovers)history.value=listItems(result.handovers);selected.value=[];owners.value={}})}
async function loadUsers(){try{users.value=listItems(await api.get('/organization/users'))}catch(e){operationError.value=errorText(e)}}
function openDelegate(){form.value={delegateUserId:'',permissions:['receive','progress','submit'],validFrom:new Date().toISOString(),validUntil:'',reason:''};formError.value='';drawer.value='delegate'}
function openAppointment(row:Row){form.value={...row,reason:''};formError.value='';drawer.value='appointment'}
async function save(){if(busy.value)return;const f=form.value;formError.value='';if(!f.reason?.trim()){formError.value='请填写变更原因';return}if(f.validFrom){const invalid=validateTimeWindow(f.validFrom,f.validUntil);if(invalid){formError.value=invalid;return}}if(drawer.value==='delegate'&&(!f.delegateUserId||!f.validUntil||!f.permissions?.length)){formError.value='请选择受托人、权限和结束时间';return}busy.value=true;try{if(drawer.value==='delegate')await api.post('/organization/delegations',{delegateUserId:f.delegateUserId,permissions:f.permissions,validFrom:f.validFrom,validUntil:f.validUntil,reason:f.reason});else await api.put('/organization/appointments/'+f.id,{version:f.version,employmentStatus:f.employmentStatus,appointmentType:f.appointmentType,validFrom:f.validFrom||null,validUntil:f.validUntil||null,enabled:f.enabled,reason:f.reason});drawer.value='';ElMessage.success('变更已保存');load()}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
async function delegationAction(row:Row,action:string){if(!allowed(row,action)||busy.value)return;if(action==='revoke'){form.value={...row,reason:''};formError.value='';drawer.value='revoke';return}busy.value=true;operationError.value='';try{await api.post(`/organization/delegations/${row.id}/activate`);auth.clear();await auth.refresh();load();ElMessage.success('已切换到明确授权的代理上下文')}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
async function revoke(){if(!form.value.reason?.trim()){formError.value='请填写撤销原因';return}busy.value=true;try{await api.post(`/organization/delegations/${form.value.id}/revoke`,{version:form.value.version,reason:form.value.reason});drawer.value='';load()}catch(e){formError.value=errorText(e)}finally{busy.value=false}}
async function leaveDelegation(){busy.value=true;try{await api.post('/organization/delegations/leave');auth.clear();await auth.refresh();load();ElMessage.success('已恢复本人岗位上下文')}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
async function selectionChange(rows:Row[]){selected.value=rows;for(const row of rows){const key=String(row.deptId);if(!targetUsers.value[key])try{targetUsers.value[key]=listItems(await api.get('/organization/users',{deptId:row.deptId})).filter(u=>u.enabled!==false)}catch(e){operationError.value=errorText(e)}}}
async function handover(){const items=selected.value.map(s=>({subTaskId:s.subTaskId??s.id,userId:owners.value[String(s.subTaskId??s.id)]??'',version:s.version}));const invalid=validateHandoverSelection(items,transferReason.value);if(invalid){operationError.value=invalid;return}busy.value=true;operationError.value='';try{await api.post('/organization/handovers',{items,reason:transferReason.value});transferReason.value='';load();ElMessage.success('交接已完成，原责任与历史保留')}catch(e){operationError.value=errorText(e)}finally{busy.value=false}}
onMounted(()=>{load();loadUsers()})
</script>
<template>
<section class="page-heading"><div><p class="eyebrow">APPOINTMENTS & HANDOVER</p><h1>岗位、代理与交接</h1><p class="muted">限定岗位和有效窗口，交接记录保留原责任人与办理原因。</p></div><el-button :loading="loading" @click="load">刷新当前状态</el-button></section>
<el-alert v-if="operationError" :title="operationError" type="error" :closable="false"/>
<div v-if="auth.me?.delegation" class="policy-banner"><div><b>当前为代理上下文</b><p>委托人 #{{ auth.me.delegation.delegatorId }} · 到期 {{ date(auth.me.delegation.validUntil) }}</p><small>仅使用本次授权的部门与操作权限。</small></div><el-button :loading="busy" @click="leaveDelegation">退出代理，恢复本人岗位</el-button></div>
<section class="panel">
<PageState :loading="loading" :error="error" @retry="load">
<el-tabs v-model="tab">
<el-tab-pane v-if="!isAdmin" label="限时代理" name="delegations"><div class="panel-heading"><p class="muted">受托人需主动进入代理上下文；到期或撤销后权限自动失效。</p><el-button v-if="canDelegate" type="primary" @click="openDelegate">新建限时委托</el-button></div><el-empty v-if="!delegations.length" description="暂无与本人相关的代理授权"/><article v-for="d in delegations" :key="d.id" class="request-card"><div class="row-between"><h3>{{ d.delegatorName||'#'+d.delegatorId }} → {{ d.delegateName||'#'+d.delegateUserId }}</h3><span class="status">{{ statuses[d.status]||d.status }}</span></div><p class="muted">公司 {{ d.companyName||'未知公司' }} · 部门 {{ d.deptName||'未知部门' }} · {{ date(d.validFrom) }} 至 {{ date(d.validUntil) }}</p><p>授权操作：{{ (d.permissions??[]).map((p:string)=>permissions[p]??p).join('、') }}</p><div class="action-strip"><el-button v-if="allowed(d,'activate')" type="primary" :loading="busy" @click="delegationAction(d,'activate')">进入代理上下文</el-button><el-button v-if="allowed(d,'revoke')" type="danger" plain :loading="busy" @click="delegationAction(d,'revoke')">撤销委托</el-button></div></article></el-tab-pane>
<el-tab-pane v-if="isAdmin" label="任职有效期" name="appointments"><div class="filter-bar"><el-select v-model="userId" filterable clearable placeholder="选择管理范围内人员" aria-label="任职人员" @change="load"><el-option v-for="u in users" :key="u.id" :value="u.id" :label="u.name"/></el-select><p class="muted">停用、离职和过期岗位立即失效；历史责任与考核快照保持原归属。</p></div><el-empty v-if="!appointments.length" description="暂无可管理任职"/><article v-for="a in appointments" :key="a.id" class="request-card"><div class="row-between"><h3>{{ a.userName||'#'+a.userId }} · {{ roles[a.role]||a.role }}</h3><el-button v-if="allowed(a,'edit')" @click="openAppointment(a)">调整任职</el-button></div><p>公司 {{ a.companyName??'全局' }} · 部门 {{ a.deptName??'—' }} · {{ a.appointmentType==='CONCURRENT'?'兼任':'主岗' }}</p><p class="muted">{{ date(a.validFrom)||'长期' }} 至 {{ date(a.validUntil)||'长期' }} · {{ ({ACTIVE:'在职',ON_LEAVE:'休假',LEFT:'离职'} as Row)[a.employmentStatus]||a.employmentStatus }} · {{ a.enabled?'启用':'停用' }} · v{{ a.version }}</p></article></el-tab-pane>
<el-tab-pane v-if="canHandover" label="在办任务交接" name="handover"><p class="notice">先选择在办任务，再指定同部门接收人。单次最多100项，版本冲突后请刷新；整批事务成功才记为完成。</p><el-table :data="tasks" style="width:100%" @selection-change="selectionChange"><el-table-column type="selection" width="48" :selectable="(row:Row)=>allowed(row,'transfer')"/><el-table-column label="任务" min-width="220"><template #default="{row}"><b>{{ row.taskTitle||row.title }}</b><p class="muted">部门 {{ row.deptName||'未知部门' }} · 当前责任人 {{ row.currentOwnerName||'未指定' }}</p></template></el-table-column><el-table-column label="新责任人" min-width="190"><template #default="{row}"><el-select v-model="owners[String(row.subTaskId??row.id)]" :disabled="!selected.some(s=>(s.subTaskId??s.id)===(row.subTaskId??row.id))" filterable placeholder="先选择该任务" aria-label="交接接收人"><el-option v-for="u in targetUsers[String(row.deptId)]||[]" :key="u.id" :value="u.id" :label="u.name" :disabled="String(u.id)===String(row.currentOwnerId)"/></el-select></template></el-table-column><el-table-column prop="version" label="版本" width="80"/></el-table><el-form label-position="top" class="handover-reason" @submit.prevent="handover"><el-form-item label="本次交接原因" required><el-input v-model="transferReason" type="textarea" :rows="3" maxlength="1000" show-word-limit/></el-form-item><el-button type="primary" native-type="submit" :disabled="!selected.length" :loading="busy">确认交接 {{ selected.length }} 项任务</el-button></el-form><h2 class="history-heading">交接历史</h2><el-empty v-if="!history.length" description="暂无范围内交接记录" :image-size="60"/><article v-for="h in history" :key="h.id" class="request-card"><b>子任务 #{{ h.subTaskId }} · {{ h.previousOwnerId??h.fromUserId??'未指定' }} → {{ h.newOwnerId??h.toUserId }}</b><p>{{ h.reason }}</p><small class="muted">办理人 #{{ h.actorId }} · {{ date(h.createdAt) }}</small></article></el-tab-pane>
</el-tabs>
</PageState><p class="scope-note">委托、任职变更和交接等敏感操作要求近期动态验证。权限和组织范围由服务端逐次校验。</p>
</section>
<el-dialog align-center class="app-card-dialog" :model-value="!!drawer" :title="drawer==='delegate'?'新建限时委托':drawer==='revoke'?'撤销代理授权':'调整岗位任职'" width="600px" :close-on-click-modal="false" @update:model-value="(value:boolean)=>{if(!value)drawer=''}"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="drawer==='revoke'?revoke():save()"><template v-if="drawer==='delegate'"><el-form-item label="同部门受托人" required><el-select v-model="form.delegateUserId" filterable><el-option v-for="u in users.filter(u=>String(u.id)!==String(auth.me?.id)&&u.enabled!==false)" :key="u.id" :label="u.name" :value="u.id"/></el-select></el-form-item><el-form-item label="明确授权的操作" required><el-checkbox-group v-model="form.permissions"><el-checkbox v-for="(label,key) in permissions" :key="key" :value="key">{{ label }}</el-checkbox></el-checkbox-group></el-form-item></template><template v-if="drawer==='appointment'"><el-form-item label="在职状态"><el-select v-model="form.employmentStatus"><el-option label="在岗" value="ACTIVE"/><el-option label="休假" value="ON_LEAVE"/><el-option label="离职" value="LEFT"/></el-select></el-form-item><el-form-item label="岗位性质"><el-radio-group v-model="form.appointmentType"><el-radio value="PRIMARY">主岗</el-radio><el-radio value="CONCURRENT">兼任</el-radio></el-radio-group></el-form-item><el-form-item label="岗位启用"><el-switch v-model="form.enabled"/></el-form-item></template><template v-if="drawer!=='revoke'"><el-form-item label="生效时间" :required="drawer==='delegate'"><el-date-picker v-model="form.validFrom" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%"/></el-form-item><el-form-item label="结束时间" :required="drawer==='delegate'"><el-date-picker v-model="form.validUntil" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%"/></el-form-item></template><el-form-item label="变更原因" required><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="1000" show-word-limit/></el-form-item><p class="muted">此操作保留审计记录，不覆盖历史责任人和冻结考核。</p><div class="form-footer"><el-button @click="drawer=''">取消</el-button><el-button type="primary" native-type="submit" :loading="busy">确认保存</el-button></div></el-form></el-dialog>
</template>
<style scoped>
.handover-reason{margin-top:24px}.history-heading{margin-top:32px}.request-card{overflow-wrap:anywhere}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.el-checkbox-group{display:flex;flex-wrap:wrap;gap:4px 16px}.policy-banner{align-items:center}.row-between{gap:12px;flex-wrap:wrap}@media(max-width:600px){.policy-banner{align-items:stretch;flex-direction:column}.filter-bar .el-select{width:100%}}
</style>
